sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {

    if (!current || !current.sys_id) {
        template.print('<p>Error: The Base record is not available.</p>');
        return;
    }

    template.print('<p><b>List of Approved Members for Base: ' + current.getDisplayValue('name') + '</b></p>');
    template.print('<ul>');

    var membershipsGR = new GlideRecord('x_752538_base_ma_0_memberships');
    membershipsGR.addQuery('base', current.sys_id);
    membershipsGR.addQuery('state', 3);
    membershipsGR.query();

    var foundMembers = false;
    while (membershipsGR.next()) {
        foundMembers = true;


        var openedById = membershipsGR.getValue('opened_by');
        var memberName = '(User not found)';

        if (openedById) {
            var userGR = new GlideRecord('sys_user');
            if (userGR.get(openedById)) {
                memberName = userGR.getDisplayValue('name');
            }
        }

        template.print('<li>' + memberName + '</li>');
    }

    if (!foundMembers) {
        template.print('<li>No approved members found.</li>');
    }

    template.print('</ul>');

})(current, template, email, email_action, event);
